import{_ as t}from"./chunks/quotas.DO0h89Vt.js";import{_ as a,o,c as h,ae as s}from"./chunks/framework.sRTLHEzD.js";const n="/heidrun_code/screenshots/features/usage_wheel.png",f=JSON.parse('{"title":"The quotas and the usage wheel","description":"The usage wheel of each pane and the status bar show the context window and the quotas of Claude and Codex, before a coding agent reaches a limit.","frontmatter":{"description":"The usage wheel of each pane and the status bar show the context window and the quotas of Claude and Codex, before a coding agent reaches a limit."},"headers":[],"relativePath":"features/quotas.md","filePath":"features/quotas.md"}'),i={name:"features/quotas.md"};function u(l,e,r,d,c,w){return o(),h("div",null,[...e[0]||(e[0]=[s('<h1 id="the-quotas-and-the-usage-wheel" tabindex="-1">The quotas and the usage wheel <a class="header-anchor" href="#the-quotas-and-the-usage-wheel" aria-label="Permalink to &quot;The quotas and the usage wheel&quot;">​</a></h1><p>A coding agent works inside two limits:</p><ul><li>The context window: the quantity of text that the coding agent can keep in mind in one chat.</li><li>The quota of your subscription: Claude and Codex let you use them only a certain quantity in 5 hours and in one week.</li></ul><p>When the coding agent reaches a limit, the work stops. Without help, you learn about the limit only when it is too late.</p><h2 id="the-usage-wheel" tabindex="-1">The usage wheel <a class="header-anchor" href="#the-usage-wheel" aria-label="Permalink to &quot;The usage wheel&quot;">​</a></h2><p>The header of each pane shows a usage wheel: a small circle that fills like a ring while the coding agent uses its context window.</p><ul><li>Below 60 percent, the usage wheel has the normal color.</li><li>From 60 to 80 percent, the usage wheel has the warning color.</li><li>Above 80 percent, the usage wheel has the critical color.</li></ul><p>Click the usage wheel to see the percent used, the number of tokens used, and the size of the context window.</p><p><img src="'+n+'" alt="The header of a Claude Code pane with its usage wheel, and the information card of the usage wheel: 7 percent used, 70,000 tokens used, and a context window of 1,000,000 tokens."></p><h2 id="the-quotas-in-the-status-bar" tabindex="-1">The quotas in the status bar <a class="header-anchor" href="#the-quotas-in-the-status-bar" aria-label="Permalink to &quot;The quotas in the status bar&quot;">​</a></h2><p>The status bar, at the bottom of the window, shows the usage of Claude and the usage of Codex. Click one of them to open its information card:</p><ul><li>The percent of the quota that you used, for 5 hours and for the week.</li><li>The time of the next reset.</li><li>The pace: your usage, compared with the usage that is expected at this time. Heidrun Code tells you the usage at the reset if you keep this pace, or how much to reduce your usage when the quota will run out early.</li></ul><p><img src="'+t+'" alt="A Claude Code pane in the light theme, with its usage wheel in the header, and under it the status bar with the Claude quota at 62% and the Codex quota at 3%." width="400"></p><p>In the Settings window, choose your working days: the pace of the weekly quota supposes that you use the coding agents on these days only. The status bar shows only the quotas of the coding agents that you enabled in the Settings window.</p><p><em>Valhalla has mead without end. Your subscription does not.</em></p>',15)])])}const m=a(i,[["render",u]]);export{f as __pageData,m as default};
